/*
#include <cstdio>
#include <cstdlib>

long long fib(int n) {
    if (n <= 1) return 1;
    long long a = 1, b = 1;
    for (int i = 2; i <= n; i++) {
        long long c = a + b;
        a = b;
        b = c;
    }
    return b;
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    int n = atoi(argv[1]);
    printf("%lld\n", fib(n));
    return 0;
}

// */
//\
fn fib(n: u64) -> u64 {//\
    if n <= 1 { return 1; }//\
    let (mut a, mut b) = (1u64, 1u64);//\
    for _ in 2..=n {//\
        let c = a + b;//\
        a = b;//\
        b = c;//\
    }//\
    b//\
}//\
//\
fn main() {//\
    let args: Vec<String> = std::env::args().collect();//\
    let n: u64 = args[1].parse().unwrap();//\
    println!("{}", fib(n));//\
}

